import csv,json
for x in 'bc':
    c={}
    for r in csv.DictReader(open(f'batch-{x}.csv')):
        if r['state'].strip()=='ready': c[r['region'].strip()]=c.get(r['region'].strip(),0)+1
    c=dict(sorted(c.items()))
    json.dump(c,open(f'{x}-summary.json','w'),indent=2)
    print(x, c, sum(c.values()))
